 1| 'use client';
 2| 
 3| import { useRouter } from 'next/navigation';
 4| import { useState, type FormEvent, type ReactNode } from 'react';
 5| 
 6| interface JsonFormProps {
 7|   action: string;
 8|   method?: 'POST' | 'PATCH' | 'DELETE';
 9|   /** Where to go after success. `{key}` is replaced with that field of the JSON response. */
10|   redirectTo?: string;
11|   submitLabel: string;
12|   className?: string;
13|   /** Clears every field when the API rejects the submission. */
14|   resetOnError?: boolean;
15|   children?: ReactNode;
16| }
17| 
18| interface ErrorBody {
19|   error?: { message?: string };
20| }
21| 
22| // Posts the form fields as JSON and shows the API error without reloading.
23| export function JsonForm({
24|   action,
25|   method = 'POST',
26|   redirectTo,
27|   submitLabel,
28|   className,
29|   resetOnError = false,
30|   children,
31| }: JsonFormProps) {
32|   const router = useRouter();
33|   const [error, setError] = useState<string | null>(null);
34|   const [pending, setPending] = useState(false);
35| 
36|   async function onSubmit(event: FormEvent<HTMLFormElement>) {
37|     event.preventDefault();
38|     const form = event.currentTarget;
39|     setPending(true);
40|     setError(null);
41|     try {
42|       const body = Object.fromEntries(new FormData(form));
43|       const response = await fetch(action, {
44|         method,
45|         headers: { 'content-type': 'application/json' },
46|         body: JSON.stringify(body),
47|       });
48|       const json = (await response.json().catch(() => ({}))) as ErrorBody & Record<string, unknown>;
49|       if (!response.ok) {
50|         setError(json.error?.message ?? 'Algo ha fallado. Inténtalo de nuevo.');
51|         if (resetOnError) form.reset();
52|         return;
53|       }
54|       if (redirectTo !== undefined) {
55|         router.push(redirectTo.replace(/\{(\w+)\}/g, (_, key: string) => String(json[key] ?? '')));
56|       }
57|       router.refresh();
58|     } finally {
59|       setPending(false);
60|     }
61|   }
62| 
63|   return (
64|     <form onSubmit={onSubmit} className={className} noValidate>
65|       {children}
66|       {error !== null && (
67|         <p role="alert" className="form-error">
68|           {error}
69|         </p>
70|       )}
71|       <button type="submit" disabled={pending}>
72|         {submitLabel}
73|       </button>
74|     </form>
75|   );
76| }
